// Helper map to quickly get all photos for any given room ID
export const ROOM_PHOTOS_MAP: Record<string, GalleryItem[]> = {};

GALLERY_ITEMS.forEach((item) => {
  if (item.roomId) {
    if (!ROOM_PHOTOS_MAP[item.roomId]) {
      ROOM_PHOTOS_MAP[item.roomId] = [];
    }
    ROOM_PHOTOS_MAP[item.roomId].push(item);
  }
});

